/**
 * Model-specific settings, read once from `import.meta.env`.
 *
 * Everything that depends on which house model is loaded (where the
 * visitor spawns, which mesh anchors the ground, how the sun path is
 * oriented) lives here so swapping the model never means editing the
 * rendering code. Each value has a neutral default that suits the
 * bundled demo house; set the matching `VITE_*` variable (see
 * `.env.example`) to adapt it to another model.
 */

/** Bundled demo model, generated by `npm run build:demo-house`. */
export const DEFAULT_HOUSE_URL = '/demo/house.glb';

/** Default spawn on the floor plane, in meters: inside the demo living room. */
const DEFAULT_SPAWN: readonly [number, number] = [-2, 0];

function parseNumber(value: string | undefined, fallback: number): number {
  if (value === undefined || value.trim() === '') return fallback;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

/** Parses `"x,z"` into a pair of finite numbers, or returns the fallback. */
function parsePair(
  value: string | undefined,
  fallback: readonly [number, number],
): [number, number] {
  const parts = (value ?? '').split(',');
  if (parts.length !== 2) return [fallback[0], fallback[1]];
  const x = Number(parts[0]);
  const z = Number(parts[1]);
  if (parts.some((p) => p.trim() === '') || !Number.isFinite(x) || !Number.isFinite(z)) {
    return [fallback[0], fallback[1]];
  }
  return [x, z];
}

/** Splits a comma-separated list into trimmed, lower-case, non-empty entries. */
function parseList(value: string | undefined): string[] {
  return (value ?? '')
    .split(',')
    .map((entry) => entry.trim().toLowerCase())
    .filter((entry) => entry.length > 0);
}

/**
 * URL of the house model (`VITE_HOUSE_URL`). The file extension selects
 * the loader: `.fbx` or `.glb` / `.gltf`.
 */
export const HOUSE_URL: string = import.meta.env.VITE_HOUSE_URL?.trim() || DEFAULT_HOUSE_URL;

/**
 * Where the first-person camera starts, as `[x, z]` in the model's
 * recentered coordinates (`VITE_HOUSE_SPAWN`). The model is centered on
 * the origin horizontally, so `0,0` is the middle of its footprint.
 */
export const HOUSE_SPAWN: readonly [number, number] = parsePair(
  import.meta.env.VITE_HOUSE_SPAWN,
  DEFAULT_SPAWN,
);

/**
 * Lower-case mesh-name fragments that identify the ground body
 * (`VITE_HOUSE_GROUND_HINTS`). When a mesh matches, its top face is
 * placed at `y = 0` so the camera stands on the ground instead of
 * clipping through a foundation. With no hints (or no match) the lowest
 * point of the model is placed at `y = 0`.
 */
export const GROUND_NAME_HINTS: readonly string[] = parseList(
  import.meta.env.VITE_HOUSE_GROUND_HINTS,
);

/**
 * Rotation of the whole sun arc around the world Y axis, in radians
 * (`VITE_SUN_PATH_ROTATION_DEG`, given in degrees). Zero rises the sun at
 * +X and sets it at -X; see `sun.ts` for the other common values.
 */
export const SUN_PATH_ROTATION_RAD: number =
  (parseNumber(import.meta.env.VITE_SUN_PATH_ROTATION_DEG, 0) * Math.PI) / 180;
